settings.custom_liquid:
{%- comment -%}
  Fitting Guide Popup
  --------------------
  এই কোডটি প্রোডাক্ট পেইজের যেকোনো জায়গায় Custom Liquid ব্লকে বসিয়ে দিলেই কাজ করবে।
  "Fitting Guide" বাটনে ক্লিক করলে পপআপ ওপেন হবে, ওভারলে বা ✕ বাটনে ক্লিক করলে ক্লোজ হবে।
{%- endcomment -%}

<button type="button" class="fg-trigger" id="fgTrigger">Fitting Guide</button>

<div class="fg-popup" id="fgPopup" aria-hidden="true">
  <div class="fg-overlay" id="fgOverlay"></div>

  <div class="fg-content" role="dialog" aria-modal="true" aria-labelledby="fgTitle">
    <button type="button" class="fg-close" id="fgClose" aria-label="Close">&times;</button>

    <h4 id="fgTitle" class="fg-title">Fitting Guide</h4>

    <div class="fg-body">
      <p>All the lasts and models launched by ACME Shoemaker are self-developed, each has been repeatedly debugged hundreds of times and continuously improved according to the experiences of different wearers, striving to achieve high adaptability for each model and last.</p>
      <p>We manufacture shoes in UK sizes. Since human foot size is very complicated, we highly recommend that you contact us and share your daily shoe wearing experiences, then based on the size chart we provide below we can discuss together to choose the right ACME Shoemaker shoe size for you.</p>
      <p>Check our size guide for a size conversion to UK / US / EU sizing on footwear.</p>

      <h3>Width Guide</h3>
      <table class="fg-table">
        <thead>
          <tr>
            <th>&nbsp;</th>
            <th>UK</th>
            <th>US</th>
            <th>ACME</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>Narrow</td>
            <td>E</td>
            <td>C</td>
            <td>E</td>
          </tr>
          <tr>
            <td>Standard</td>
            <td>F</td>
            <td>D</td>
            <td>F</td>
          </tr>
          <tr>
            <td>Wide</td>
            <td>G</td>
            <td>E</td>
            <td>G</td>
          </tr>
        </tbody>
      </table>

      <p>The width standard of ACME Shoemaker shoes is based on the UK shoe size (Sioux), which is optimized according to our lasts and the accumulation of data on customer's foot shape, the standard width of ACME Shoemaker shoe is F.</p>

      <h3>Size Guide</h3>
      <table class="fg-table">
        <thead>
          <tr>
            <th>ACME</th>
            <th>UK</th>
            <th>US</th>
            <th>EU</th>
          </tr>
        </thead>
        <tbody>
          <tr><td>5</td><td>5</td><td>6</td><td>39</td></tr>
          <tr><td>5.5</td><td>5.5</td><td>6.5</td><td>39.5</td></tr>
          <tr><td>6</td><td>6</td><td>7</td><td>40</td></tr>
          <tr><td>6.5</td><td>6.5</td><td>7.5</td><td>40.5</td></tr>
          <tr><td>7</td><td>7</td><td>8</td><td>41</td></tr>
          <tr><td>7.5</td><td>7.5</td><td>8.5</td><td>41.5</td></tr>
          <tr><td>8</td><td>8</td><td>9</td><td>42</td></tr>
          <tr><td>8.5</td><td>8.5</td><td>9.5</td><td>42.5</td></tr>
          <tr><td>9</td><td>9</td><td>10</td><td>43</td></tr>
          <tr><td>9.5</td><td>9.5</td><td>10.5</td><td>43.5</td></tr>
          <tr><td>10</td><td>10</td><td>11</td><td>44</td></tr>
          <tr><td>10.5</td><td>10.5</td><td>11.5</td><td>44.5</td></tr>
          <tr><td>11</td><td>11</td><td>12</td><td>45</td></tr>
          <tr><td>11.5</td><td>11.5</td><td>12.5</td><td>45.5</td></tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<style>
  .fg-trigger {
    background: #111;
    color: #fff;
    border: 1px solid #111;
    padding: 12px 22px;
    font-size: 13px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    cursor: pointer;
    transition: background 0.2s ease, color 0.2s ease;
  }
  .fg-trigger:hover {
    background: #fff;
    color: #111;
  }

  .fg-popup {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    margin: 0 !important;
    z-index: 999999;
    display: none;
  }
  .fg-popup.is-open {
    display: block;
  }

  .fg-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
  }

  .fg-content {
    position: relative;
    width: 100%;
    max-width: 820px;
    height: 100vh;
    margin: 0 auto !important;
    background: #fff;
    color: #333;
    padding: 60px 50px 80px;
    overflow-y: auto;
    box-shadow: 0 0 40px rgba(0, 0, 0, 0.15);
    box-sizing: border-box;
  }

  .fg-close {
    position: absolute;
    top: 22px;
    right: 24px;
    background: transparent;
    border: none;
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
    color: #333;
  }
  .fg-close:hover {
    color: #111;
  }

  .fg-title {
    max-width: 760px;
    margin: 0 auto 36px;
    font-size: 26px;
    font-weight: 400;
    text-align: center;
    text-transform: none;
    letter-spacing: 0.01em;
    border-bottom: none;
    padding-bottom: 0;
    color: #000;
  }

  .fg-body {
    max-width: 760px;
    margin: 0 auto;
  }

  .fg-body p {
    font-size: 15px;
    line-height: 1.7;
    margin: 0 0 20px;
    color: #555;
  }

  .fg-body h3 {
    font-size: 22px;
    font-weight: 400;
    text-transform: none;
    letter-spacing: normal;
    margin: 36px 0 20px;
    color: #222;
  }

  .fg-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
    font-size: 14px;
  }
  .fg-table th,
  .fg-table td {
    border: 1px solid #e0e0e0;
    padding: 14px 12px;
    text-align: center;
  }
  .fg-table thead th {
    background: #111;
    color: #fff;
    text-transform: none;
    font-size: 14px;
    font-weight: 400;
    letter-spacing: normal;
    border-color: #111;
  }
  .fg-table tbody tr {
    background: #fff;
  }

  @media (max-width: 480px) {
    .fg-content {
      max-width: 100%;
      padding: 50px 18px 60px;
    }
    .fg-close {
      top: 16px;
      right: 16px;
    }
    .fg-title {
      font-size: 20px;
    }
    .fg-body h3 {
      font-size: 18px;
    }
    .fg-table th,
    .fg-table td {
      padding: 8px 6px;
      font-size: 12px;
    }
  }
</style>

<script>
  (function () {
    var trigger = document.getElementById('fgTrigger');
    var popup = document.getElementById('fgPopup');
    var overlay = document.getElementById('fgOverlay');
    var closeBtn = document.getElementById('fgClose');

    /* Shopify থিমে অনেক সময় parent element-এ transform/perspective থাকে,
       যেটার কারণে position:fixed viewport এর বদলে ওই parent-এর সাপেক্ষে বসে যায়
       (ফলে পপআপ ডান পাশে/ভুল জায়গায় দেখা যায়)।
       এটা এড়াতে popup-কে সরাসরি <body>-এর child বানিয়ে দিচ্ছি। */
    document.body.appendChild(popup);

    function openPopup() {
      popup.classList.add('is-open');
      popup.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }

    function closePopup() {
      popup.classList.remove('is-open');
      popup.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
    }

    trigger.addEventListener('click', openPopup);
    overlay.addEventListener('click', closePopup);
    closeBtn.addEventListener('click', closePopup);

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && popup.classList.contains('is-open')) {
        closePopup();
      }
    });
  })();
</script>

{%- comment -%} Fully Bespoke Size Toggle - v3 (targets exact product-form id) {%- endcomment -%}
{%- liquid
  assign size_option_title = 'Size'
  for block in section.blocks
    if block.type == 'variant_picker'
      if block.settings.size_title != blank
        assign size_option_title = block.settings.size_title | split: ',' | first | strip
      endif
    endif
  endfor
-%}
<div class="bespoke-wrap" id="bespoke-wrap-{{ section.id }}" data-size-title="{{ size_option_title | escape }}" data-section-id="{{ section.id }}">

  <button type="button" class="bespoke-toggle-btn" id="bespoke-toggle-{{ section.id }}">
    Size: Bespoke
  </button>

  <div class="bespoke-panel" id="bespoke-panel-{{ section.id }}">

    <label for="bespoke-size-{{ section.id }}">please write here your shoe size normaly, which size shoes you wear</label>
    <textarea
      id="bespoke-size-{{ section.id }}"
      name="properties[Custom Size / Measurement]"
      rows="3"
      placeholder="e.g., EU 42, US 9, UK 8"></textarea>

    <label for="bespoke-contact-{{ section.id }}">Please enter your email or whatsapp number</label>
    <input
      type="text"
      id="bespoke-contact-{{ section.id }}"
      name="properties[Contact (Email / WhatsApp)]">

    <input type="hidden" name="properties[Size Type]" value="" id="bespoke-hidden-type-{{ section.id }}">

    <p class="bespoke-hint">(it's best if you put your WhatsApp number) so that our representative will contact you to do the perfect measurement of your feet. We make every pair of shoes to the exact measurements of our client's feet. We use only the best quality materials and bespoke construction at a real price.)</p>
  </div>

  <div class="bespoke-info-box">

    <p>After taking precise measurements of your feet, we create a custom wooden last crafted exclusively for your unique foot shape and dimensions. This personalized last ensures every pair is made to your exact specifications for an exceptional fit.</p>
    <p>We offer 100% true bespoke footwear—never semi-bespoke. Every pair is individually handcrafted from the ground up, using your personal last, delivering unmatched fit, comfort, elegance, and craftsmanship.</p>
  </div>
</div>

<style>
  #bespoke-wrap-{{ section.id }} {
    font-family: inherit;
    margin-bottom: 20px;
  }

  .bespoke-toggle-btn {
    display: inline-block;
    white-space: nowrap;
    padding: 10px 18px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.02em;
    border: 1px solid rgba(255,255,255,0.35);
    background: transparent;
    color: #ffffff;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-left: auto;
  }
  .bespoke-toggle-btn:hover { border-color: #ffffff; }
  .bespoke-toggle-btn.is-active {
    background: transparent;
    color: #ffffff;
    border-color: #ffffff;
  }

  .bespoke-variant-disabled {
    opacity: 0.35;
    pointer-events: none;
    filter: grayscale(40%);
    position: relative;
  }
  .bespoke-variant-disabled::after {
    content: "Disabled — Fully Bespoke selected";
    display: block;
    font-size: 12px;
    color: #ffffff;
    opacity: 0.7;
    margin-top: 6px;
  }

  .bespoke-panel {
    margin-top: 16px;
    padding: 16px;
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 6px;
    background: rgba(255,255,255,0.03);
  }
  .bespoke-panel label {
    display: block;
    font-size: 13px;
    font-weight: 500;
    color: #ffffff;
    margin-bottom: 6px;
  }
  .bespoke-panel textarea,
  .bespoke-panel input[type="text"] {
    width: 100%;
    box-sizing: border-box;
    padding: 10px 12px;
    margin-bottom: 14px;
    background: #1a1a1a;
    border: 1px solid rgba(255,255,255,0.25);
    border-radius: 4px;
    color: #ffffff;
    font-size: 14px;
  }
  .bespoke-panel textarea::placeholder,
  .bespoke-panel input[type="text"]::placeholder { color: rgba(255,255,255,0.45); }
  .bespoke-panel textarea:focus,
  .bespoke-panel input[type="text"]:focus {
    outline: none;
    border-color: #ffffff;
    background: #222222;
  }
  .bespoke-hint {
    font-size: 12px;
    color: rgba(255,255,255,0.55);
    margin: 0;
  }

  .bespoke-info-box {
    margin-top: 14px;
    padding: 14px 16px;
    border: 1px dashed rgba(255,255,255,0.3);
    border-radius: 6px;
    background: rgba(255,255,255,0.05);
  }
  .bespoke-info-box p {
    font-size: 12px;
    line-height: 1.6;
    color: rgba(255,255,255,0.75);
    margin: 0 0 8px 0;
  }
  .bespoke-info-box p:first-child {
    font-weight: 600;
    color: #ffffff;
  }
  .bespoke-info-box p:last-child {
    margin-bottom: 0;
  }
</style>

<script>
(function () {
  function attach() {
    var wrap = document.getElementById('bespoke-wrap-{{ section.id }}');
    if (!wrap) return;

    var sectionId    = wrap.dataset.sectionId;
    var toggleBtn    = document.getElementById('bespoke-toggle-{{ section.id }}');
    var panel        = document.getElementById('bespoke-panel-{{ section.id }}');
    var hiddenType   = document.getElementById('bespoke-hidden-type-{{ section.id }}');
    var sizeField    = document.getElementById('bespoke-size-{{ section.id }}');
    var contactField = document.getElementById('bespoke-contact-{{ section.id }}');
    var sizeTitle    = (wrap.dataset.sizeTitle || 'Size').toLowerCase();

    /* ---- 1) Find the EXACT cart form used by this theme's variant-picker.js ---- */
    var cartForm = document.getElementById('product-form-' + sectionId);

    if (cartForm && !wrap.dataset.moved) {
      /* Physically move our whole block to be the FIRST child inside the real
         <form>. This guarantees the properties[...] fields are true form
         descendants, so they work with FormData() AND with any manual
         "collect all named fields inside the form" logic the theme uses. */
      cartForm.insertBefore(wrap, cartForm.firstChild);
      wrap.dataset.moved = 'true';
    }

    /* ---- 2) Move the "Fully Bespoke" button next to the Size option label ---- */
    var variantPicker = document.querySelector('variant-picker[data-section-id="' + sectionId + '"]');
    var variantContainer = null;
    var labelEl = null;

    if (variantPicker) {
      var optionFields = variantPicker.querySelectorAll('[data-picker-field]');
      optionFields.forEach(function (field) {
        if (variantContainer) return;
        var legend = field.querySelector('legend, label, [class*="label"]');
        var text = (legend ? legend.textContent : field.textContent || '').trim().toLowerCase();
        if (text.indexOf(sizeTitle) === 0) {
          variantContainer = field;
          labelEl = legend;
        }
      });
    }

    if (labelEl && !labelEl.dataset.bespokeAttached) {
      labelEl.style.display = 'flex';
      labelEl.style.alignItems = 'center';
      labelEl.style.justifyContent = 'space-between';
      labelEl.style.gap = '10px';
      labelEl.appendChild(toggleBtn);
      labelEl.dataset.bespokeAttached = 'true';
    }

    var isActive = false;
    function setActive(active) {
      isActive = active;
      toggleBtn.classList.toggle('is-active', active);
      panel.style.display = active ? '' : 'none';
      hiddenType.value = active ? 'Fully Bespoke' : '';

      if (active) {
        sizeField.setAttribute('required', 'required');
        contactField.setAttribute('required', 'required');
      } else {
        sizeField.removeAttribute('required');
        contactField.removeAttribute('required');
        sizeField.value = '';
        contactField.value = '';
      }

      if (variantContainer) {
        variantContainer.classList.toggle('bespoke-variant-disabled', active);
      }
    }

    toggleBtn.addEventListener('click', function () {
      setActive(!isActive);
    });

    if (cartForm) {
      cartForm.addEventListener('submit', function (e) {
        if (isActive && (!sizeField.value.trim() || !contactField.value.trim())) {
          e.preventDefault();
          alert('Please enter your custom size and Email/WhatsApp number.');
        }
      });
    }

    /* Default state: panel open / Bespoke selected on load */
    setActive(true);
  }

  /* Retry briefly in case the form / variant-picker custom element
     hasn't finished upgrading yet when this script runs. */
  var tries = 0;
  var interval = setInterval(function () {
    tries++;
    var form = document.getElementById('product-form-{{ section.id }}');
    if (form || tries > 20) {
      clearInterval(interval);
      attach();
    }
  }, 100);
})();
</script>
